package cn.iocoder.yudao.module.pms.project.controller.admin.projects;
import cn.iocoder.yudao.module.system.api.user.ActiveUserSelectionApi;import cn.iocoder.yudao.module.system.api.user.ProjectMemberIdentityScopeProvider;
import cn.iocoder.yudao.module.pms.project.controller.admin.projects.vo.ProjectMemberFilterPageReqVO;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.test.util.ReflectionTestUtils;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class ProjectMemberFilterControllerTest {
 @Test void onlyForwardsFieldKeywordAndPaginationToTrustedSystemApi(){var api=mock(ActiveUserSelectionApi.class);var controller=new ProjectSelectionController(mock(cn.iocoder.yudao.module.pms.project.service.projectselection.ProjectSelectionQueryService.class));ReflectionTestUtils.setField(controller,"activeUserSelectionApi",api);var request=new MockHttpServletRequest();request.addParameter("field","MANAGER");var query=new ProjectMemberFilterPageReqVO();query.setField(ProjectMemberIdentityScopeProvider.Filter.MANAGER);query.setKeyword("name");query.setPageNo(2);query.setPageSize(20);controller.memberFilterOptions(query,request);verify(api).pageProjectMembers(new ActiveUserSelectionApi.MemberFilterQuery(2,20,"name",ProjectMemberIdentityScopeProvider.Filter.MANAGER));}
 @Test void callerCannotSupplyIdsTenantActorOrPermissionScope(){var api=mock(ActiveUserSelectionApi.class);var controller=new ProjectSelectionController(mock(cn.iocoder.yudao.module.pms.project.service.projectselection.ProjectSelectionQueryService.class));ReflectionTestUtils.setField(controller,"activeUserSelectionApi",api);for(var field:java.util.List.of("userIds","tenantId","actorId","projectIds","readScope")){var request=new MockHttpServletRequest();request.addParameter(field,"1");assertThrows(RuntimeException.class,()->controller.memberFilterOptions(new ProjectMemberFilterPageReqVO(),request));}verifyNoInteractions(api);}
}
